using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table: index i maps to the bit-reversed value of byte i.
    private static readonly byte[] LookupTable = CreateLookupTable();

    private static byte[] CreateLookupTable()
    {
        var table = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            int b = i;
            b = ((b & 0xF0) >> 4) | ((b & 0x0F) << 4);
            b = ((b & 0xCC) >> 2) | ((b & 0x33) << 2);
            b = ((b & 0xAA) >> 1) | ((b & 0x55) << 1);
            table[i] = (byte)b;
        }
        return table;
    }

    public static void ReverseInPlace(Span<byte> data)
    {
        if (Ssse3.IsSupported)
        {
            ReverseInPlaceSsse3(data);
            return;
        }

        if (AdvSimd.IsSupported)
        {
            ReverseInPlaceNeon(data);
            return;
        }

        ReverseInPlaceScalar(data);
    }

    /// <summary>
    /// SSSE3 path: uses PSHUFB as a parallel nibble lookup to reverse bits
    /// in 16 bytes at a time (or 32 with AVX2).
    /// </summary>
    private static void ReverseInPlaceSsse3(Span<byte> data)
    {
        // Nibble reverse lookup: reverses the 4 bits and places result in the correct half.
        // Low nibble table: reverse(nibble) << 4
        Vector128<byte> lowNibbleLut = Vector128.Create(
            (byte)0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0,
            0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0);
        // High nibble table: reverse(nibble)
        Vector128<byte> highNibbleLut = Vector128.Create(
            (byte)0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
            0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F);
        Vector128<byte> mask0F = Vector128.Create((byte)0x0F);

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int len = data.Length;

        if (Avx2.IsSupported)
        {
            var lowNibbleLut256 = Vector256.Create(lowNibbleLut, lowNibbleLut);
            var highNibbleLut256 = Vector256.Create(highNibbleLut, highNibbleLut);
            var mask0F256 = Vector256.Create((byte)0x0F);

            int limit = len - 31;
            for (; i <= limit; i += 32)
            {
                var vec = Unsafe.As<byte, Vector256<byte>>(ref Unsafe.Add(ref ptr, i));
                var lo = Avx2.And(vec, mask0F256);
                var hi = Avx2.And(Avx2.ShiftRightLogical(vec.AsUInt16(), 4).AsByte(), mask0F256);
                var reversedLo = Avx2.Shuffle(lowNibbleLut256, lo);
                var reversedHi = Avx2.Shuffle(highNibbleLut256, hi);
                var result = Avx2.Or(reversedLo, reversedHi);
                Unsafe.As<byte, Vector256<byte>>(ref Unsafe.Add(ref ptr, i)) = result;
            }
        }

        // SSE 128-bit loop for remaining or primary path
        {
            int limit = len - 15;
            for (; i <= limit; i += 16)
            {
                var vec = Unsafe.As<byte, Vector128<byte>>(ref Unsafe.Add(ref ptr, i));
                var lo = Sse2.And(vec, mask0F);
                var hi = Sse2.And(Sse2.ShiftRightLogical(vec.AsUInt16(), 4).AsByte(), mask0F);
                var reversedLo = Ssse3.Shuffle(lowNibbleLut, lo);
                var reversedHi = Ssse3.Shuffle(highNibbleLut, hi);
                var result = Sse2.Or(reversedLo, reversedHi);
                Unsafe.As<byte, Vector128<byte>>(ref Unsafe.Add(ref ptr, i)) = result;
            }
        }

        // Scalar tail
        ref byte tableRef = ref MemoryMarshal.GetArrayDataReference(LookupTable);
        for (; i < len; i++)
        {
            ref byte b = ref Unsafe.Add(ref ptr, i);
            b = Unsafe.Add(ref tableRef, b);
        }
    }

    /// <summary>
    /// ARM NEON path: uses VTBL/vector lookup for nibble-based bit reversal.
    /// </summary>
    private static void ReverseInPlaceNeon(Span<byte> data)
    {
        Vector128<byte> lowNibbleLut = Vector128.Create(
            (byte)0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0,
            0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0);
        Vector128<byte> highNibbleLut = Vector128.Create(
            (byte)0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
            0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F);
        Vector128<byte> mask0F = Vector128.Create((byte)0x0F);

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int len = data.Length;
        int limit = len - 15;

        for (; i <= limit; i += 16)
        {
            var vec = Unsafe.As<byte, Vector128<byte>>(ref Unsafe.Add(ref ptr, i));
            var lo = AdvSimd.And(vec, mask0F);
            var hi = AdvSimd.And(AdvSimd.ShiftRightLogical(vec, 4), mask0F);
            var reversedLo = AdvSimd.Arm64.VectorTableLookup(lowNibbleLut, lo);
            var reversedHi = AdvSimd.Arm64.VectorTableLookup(highNibbleLut, hi);
            var result = AdvSimd.Or(reversedLo, reversedHi);
            Unsafe.As<byte, Vector128<byte>>(ref Unsafe.Add(ref ptr, i)) = result;
        }

        // Scalar tail
        ref byte tableRef = ref MemoryMarshal.GetArrayDataReference(LookupTable);
        for (; i < len; i++)
        {
            ref byte b = ref Unsafe.Add(ref ptr, i);
            b = Unsafe.Add(ref tableRef, b);
        }
    }

    /// <summary>
    /// Scalar fallback using a precomputed 256-byte lookup table.
    /// </summary>
    private static void ReverseInPlaceScalar(Span<byte> data)
    {
        ref byte ptr = ref MemoryMarshal.GetReference(data);
        ref byte tableRef = ref MemoryMarshal.GetArrayDataReference(LookupTable);
        int len = data.Length;

        for (int i = 0; i < len; i++)
        {
            ref byte b = ref Unsafe.Add(ref ptr, i);
            b = Unsafe.Add(ref tableRef, b);
        }
    }
}

